// Define stdout_capture_t struct since it's not in headers
typedef struct {
    char *buffer;
    size_t buffer_size;
    int pipe_read_fd;
    int pipe_write_fd;
    int saved_stdout_fd;
} stdout_capture_t;

// ========== Searched From Pool - Assertion Operations ==========

// Function: assert_stdout_equals (from helper pool)
void assert_stdout_equals(stdout_capture_t *cap, const char *expected) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strcmp(actual, expected) != 0) {
        fprintf(stderr, "Stdout assertion failed:
");
        fprintf(stderr, "  Expected: "%s"
", expected);
        fprintf(stderr, "  Actual:   "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_contains (from helper pool)
void assert_stdout_contains(stdout_capture_t *cap, const char *expected_substring) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strstr(actual, expected_substring) == NULL) {
        fprintf(stderr, "Stdout assertion failed (substring not found):
");
        fprintf(stderr, "  Expected substring: "%s"
", expected_substring);
        fprintf(stderr, "  Actual output:      "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_not_empty (from helper pool)
void assert_stdout_not_empty(stdout_capture_t *cap) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strlen(actual) == 0) {
        fprintf(stderr, "Stdout assertion failed: output was empty
");
        free(actual);
        exit(1);
    }
    free(actual);
}

// ========== Created - Assertion Operations ==========

// Asserts that the add function returns the expected sum of two integers
void helper_assert_add(int a, int b, int expected_sum) {
    int result = add(a, b);
    assert(result == expected_sum);
}

// Asserts that the factorial function returns the correct factorial for a positive integer
void helper_assert_factorial(int n, int expected_factorial) {
    int result = factorial(n);
    assert(result == expected_factorial);
}

// Asserts that the factorial function returns -1 for a negative input
void helper_assert_factorial_negative(int n) {
    int result = factorial(n);
    assert(result == -1);
}

// Asserts that the factorial function returns 1 for input 0
void helper_assert_factorial_zero() {
    int result = factorial(0);
    assert(result == 1);
}

// ========== Searched From Pool - Utility Operations ==========

// Function: capture_stdout_start (from helper pool)
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(cap->pipe_write_fd);
    /* Restore original stdout */
    dup2(cap->saved_stdout_fd, STDOUT_FILENO);
    close(cap->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(cap->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(cap->pipe_read_fd);
                free(cap);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buffer;
}


